import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { expect, test } from '@playwright/test'

import { uploadFixture } from '../helpers/fileUpload'

const currentDir = path.dirname(fileURLToPath(import.meta.url))
// Generated by tools/make-jww-sample.mjs; also served as a demo sample.
const jwwSamplePath = path.resolve(
  currentDir,
  '../../../../resources/cad-data/samples/jww-sample.jww'
)

test('opens a Jw_cad (.jww) drawing through the JWW parser worker', async ({
  page
}) => {
  const pageErrors: string[] = []
  page.on('pageerror', error => pageErrors.push(error.message))
  const wasmResponse = page.waitForResponse(response =>
    response.url().endsWith('/jww-parser.wasm')
  )

  await page.goto('/')
  const fileInput = page.locator('input[type="file"]').first()
  await expect(fileInput).toHaveAttribute('accept', /\.jww/)
  await uploadFixture(page, jwwSamplePath)

  expect((await wasmResponse).ok()).toBeTruthy()
  await expect(page.locator('.ml-cad-container canvas').first()).toBeVisible()
  await expect(page.getByText('jww-sample.jww').first()).toBeVisible()
  await expect(page.getByText(/Failed to open/)).toHaveCount(0)
  expect(pageErrors).toEqual([])
})
